holes0 = [100, 500, 200, 300, 600]
reqs = [212, 417, 112, 426]

def run(mode):
    holes = holes0[:]
    out = []
    for r in reqs:
        idx = None
        if mode == 'first':
            for i, h in enumerate(holes):
                if h >= r:
                    idx = i
                    break
        elif mode == 'best':
            best = None
            for i, h in enumerate(holes):
                if h >= r and (best is None or h < holes[best]):
                    best = i
            idx = best
        else:
            best = None
            for i, h in enumerate(holes):
                if h >= r and (best is None or h > holes[best]):
                    best = i
            idx = best
        if idx is None:
            continue
        out.append(holes[idx] - r)
        holes[idx] -= r
        if holes[idx] == 0:
            holes.pop(idx)
    return out

for mode in ['first', 'best', 'worst']:
    for v in run(mode):
        print(v)
